#!/usr/bin/env bash
# Installs AFH's terminal app on macOS or Linux, for this user only (no sudo):
#
#   curl -fsSL https://agentflowharness.com/install.sh | bash
#
# It downloads the newest release from GitHub, checks its SHA-256, unpacks it to ~/.afh/cli and puts
# `afh` on your PATH. `afh uninstall` undoes this; your threads, settings and keys stay.
set -euo pipefail

temp="" staging="" worker="" animate=""  # the exit trap runs after main has returned
cleanup() {
  if [ -n "$worker" ]; then kill "$worker" 2>/dev/null || true; fi
  if [ -n "$temp" ]; then rm -rf "$temp"; fi
  if [ -n "$staging" ]; then rm -rf "$staging"; fi
  if [ -n "$animate" ]; then printf '\033[0m\033[?25h'; fi
}
trap cleanup EXIT
trap 'exit 130' INT TERM

# The animated mark, as in the app: a letter is a pixel, and two pixels stack in a cell.
# mark:start, written by scripts/bake-mark.py
mark_cols=24
mark_rows=8
mark_letters='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'
mark_back_true='14;13;13'
mark_back_256=233
mark_blocks=(' ' '▀' '▘' '▝' '▖' '▗' '▚' '▞' '▁' '▂' '▃' '▄' '▅' '▆' '▇' '▏' '▎' '▍' '▌' '▋' '▊' '▉')
mark_true=('255;177;31' '236;159;32' '236;156;34' '236;154;35' '236;151;37' '236;148;38' '236;145;40' '236;143;41' '236;140;43' '236;137;44' '236;134;46' '236;132;47' '236;129;49' '236;126;50' '236;124;52' '255;122;61' '255;119;71' '239;121;54' '238;117;57' '236;105;70' '236;102;73' '236;100;74' '236;98;76' '236;95;77' '236;93;79' '236;91;81' '236;89;82' '222;107;55' '193;94;49' '255;74;104' '245;71;100' '255;61;138' '236;86;84' '236;84;86' '236;81;88' '236;78;91' '236;75;92' '234;64;110' '231;52;130' '191;76;63' '189;57;79' '159;78;42' '230;50;131' '228;48;132' '227;46;133' '225;44;133' '224;42;134' '222;40;135' '221;38;136' '217;33;138' '213;29;140' '224;22;154' '218;22;150' '211;27;141' '210;24;142' '196;21;135' '173;20;120' '162;51;69' '159;50;68' '152;19;106' '140;18;98' '14;13;13')
mark_256=(214 214 214 208 208 208 208 208 208 208 208 208 209 209 209 209 209 209 209 203 203 203 203 203 203 203 203 167 131 203 203 204 203 203 203 203 203 167 168 131 131 130 168 168 162 162 162 162 162 162 162 162 162 162 162 162 126 131 131 89 89 233)
mark_line_true=('255;177;31' '255;169;37' '255;161;43' '255;152;49' '255;144;54' '255;136;60' '255;128;66' '255;119;72' '255;111;78' '255;103;84' '255;95;89' '255;86;95' '255;78;101' '254;72;106' '251;68;110' '249;64;114' '246;59;118' '244;55;122' '241;51;126' '239;47;130' '236;43;134' '234;39;138' '231;34;142' '229;30;146' '226;26;150' '224;22;154')
mark_line_256=(214 214 214 209 209 209 209 209 203 203 203 203 203 203 203 203 204 204 204 198 198 162 162 162 162 162)
mark_frames=(
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
  ''
)
# mark:end
mark_fg=() mark_bg=() place=() drawn=() line=()
card="" dim=""
rest=$((${#mark_frames[@]} - 1))
width=$((mark_cols + 2))
height=$((mark_rows + 2))

# True colour where the terminal says it has it, 256 colours elsewhere: macOS Terminal has no true colour.
load_mark() {
  local i code
  case "${COLORTERM:-}" in
    *truecolor* | *24bit*)
      for ((i = 0; i < ${#mark_true[@]}; i++)); do mark_fg[i]="38;2;${mark_true[i]}"; mark_bg[i]="48;2;${mark_true[i]}"; done
      for ((i = 0; i < width; i++)); do line[i]="38;2;${mark_line_true[i]}"; done
      card="48;2;$mark_back_true"
      dim="38;2;120;114;108"
      ;;
    *)
      for ((i = 0; i < ${#mark_256[@]}; i++)); do mark_fg[i]="38;5;${mark_256[i]}"; mark_bg[i]="48;5;${mark_256[i]}"; done
      for ((i = 0; i < width; i++)); do line[i]="38;5;${mark_line_256[i]}"; done
      card="48;5;$mark_back_256"
      dim="38;5;244"
      ;;
  esac
  # a letter's place, found by its code: the bash on a Mac has no associative arrays
  for ((i = 0; i < ${#mark_letters}; i++)); do
    printf -v code '%d' "'${mark_letters:i:1}"
    place[code]=$i
  done
}

draw_mark() {
  local n="$1" f="${mark_frames[$1]}" text="" x y at a b c ink behind last
  if [ -n "${drawn[n]:-}" ]; then return; fi
  for ((y = 0; y < mark_rows; y++)); do
    text+=$'  \033['"${card}m "
    last=""
    for ((x = 0; x < mark_cols; x++)); do
      at=$((3 * (y * mark_cols + x)))
      printf -v a '%d' "'${f:at:1}"
      printf -v b '%d' "'${f:at + 1:1}"
      printf -v c '%d' "'${f:at + 2:1}"
      ink="${place[b]}" behind="${place[c]}"
      if [ "$ink.$behind" != "$last" ]; then
        text+=$'\033['"${mark_fg[ink]};${mark_bg[behind]}m"
        last="$ink.$behind"
      fi
      text+="${mark_blocks[${place[a]}]}"
    done
    text+=$'\033['"${card}m "$'\033[0m\033[K\n'
  done
  drawn[n]="$text"
}

# fill is 0 to 1000, n is the frame of the mark
frame() {
  local fill="$1" n="$2" status="$3" first="$4"
  local edge=$((fill * width / 1000)) text="" c
  if [ -z "$first" ]; then text=$'\033['"${height}A"$'\r'; fi
  draw_mark "$n"
  text+="${drawn[n]}"$'\033[K\n  '
  for ((c = 0; c < width; c++)); do
    if [ "$c" -lt "$edge" ]; then text+=$'\033['"${line[c]}m━"; else text+=$'\033['"${dim}m━"; fi
  done
  text+=$'\033[0m\033[K\n  '"$status"$'\033[K'
  printf '%s' "$text"
}

# Everything that takes time. It runs beside the animation and reports through files in $temp.
work() {
  local base="$1" home="$2" asset="$3" versions="$4"
  fail() { printf '%s' "$1" > "$temp/failed"; exit 1; }

  curl -fsSIL "$base/$asset" 2>/dev/null | tr -d '\r' | awk 'tolower($1) == "content-length:" { n = $2 } END { print n + 0 }' > "$temp/total" || true
  curl -fsSL "$base/afh-checksums.txt" -o "$temp/afh-checksums.txt" || fail "Couldn't reach the download. Check your connection."
  curl -fsSL "$base/$asset" -o "$temp/$asset" || fail "The download stopped. Check your connection."
  : > "$temp/unpack"

  local want got
  want="$(grep -F "$asset" "$temp/afh-checksums.txt" | head -n 1 | cut -d' ' -f1)"
  if [ -z "$want" ]; then fail "No checksum for $asset."; fi
  if command -v sha256sum >/dev/null 2>&1; then got="$(sha256sum "$temp/$asset" | cut -d' ' -f1)"; else got="$(shasum -a 256 "$temp/$asset" | cut -d' ' -f1)"; fi
  if [ "$want" != "$got" ]; then fail "The download didn't match its checksum, so nothing was installed."; fi

  mkdir -p "$staging"
  tar -xzf "$temp/$asset" -C "$staging"
  local version
  version="$("$staging/afh/afh" --version | sed 's/^afh //')" || fail "The downloaded program didn't start."
  if [ -z "$version" ]; then fail "The downloaded program didn't start."; fi

  rm -rf "${versions:?}/$version"
  mv "$staging" "$versions/$version"

  mkdir -p "$home/bin"
  printf '#!/bin/sh\nexec "%s" "$@"\n' "$versions/$version/afh/afh" > "$home/bin/afh"
  chmod 755 "$home/bin/afh"

  local line="export PATH=\"$home/bin:\$PATH\"  # added by AFH"
  case ":$PATH:" in
    *":$home/bin:"*) ;;
    *)
      for rc in "$HOME/.zshrc" "$HOME/.bashrc" "$HOME/.profile"; do
        if [ -f "$rc" ] || [ "$rc" = "$HOME/.profile" ]; then
          grep -qF ".afh/bin" "$rc" 2>/dev/null || printf '\n%s\n' "$line" >> "$rc"
          : > "$temp/added"
        fi
      done
      ;;
  esac
  printf '%s' "$version" > "$temp/version"
}

main() {
  local base="${AFH_DOWNLOAD_BASE:-https://github.com/Lucifer-xD/agent-flow-harness/releases/latest/download}"
  local home="${AFH_HOME:-$HOME/.afh}"
  local os arch asset
  os="$(uname -s)"
  arch="$(uname -m)"
  case "$os-$arch" in
    Darwin-arm64) asset="afh-macos-arm64.tar.gz" ;;
    Darwin-x86_64) asset="afh-macos-x64.tar.gz" ;;
    Linux-x86_64) asset="afh-linux-x64.tar.gz" ;;
    *) echo "There's no AFH build for $os on $arch yet." >&2; exit 1 ;;
  esac

  local versions="$home/cli/versions"
  temp="$(mktemp -d)"
  staging="$versions/.new-$$"
  mkdir -p "$versions"

  if [ -t 1 ] && [ "${TERM:-dumb}" != "dumb" ]; then
    case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
      *[Uu][Tt][Ff]-8* | *[Uu][Tt][Ff]8*) animate="yes" ;;
    esac
  fi

  # stdin is this script when it arrives through a pipe, so nothing here may read it
  (work "$base" "$home" "$asset" "$versions") </dev/null >/dev/null 2>"$temp/errors" &
  worker=$!

  local shown=0 tick=0 first="yes" total got goal
  if [ -n "$animate" ]; then
    load_mark
    printf '\033[?25l\n'
    while kill -0 "$worker" 2>/dev/null; do
      if [ -f "$temp/unpack" ]; then
        shown=$((shown + (970 - shown) / 30))
      else
        total="$(cat "$temp/total" 2>/dev/null || true)"
        goal=0
        if [ -f "$temp/$asset" ] && [ "${total:-0}" -gt 0 ]; then
          got="$(wc -c < "$temp/$asset")"
          goal=$((got * 800 / total))
        fi
        shown=$((shown + (goal - shown) / 3))
      fi
      frame "$shown" "$((tick % rest))" "Installing AFH  $((shown / 10))%" "$first"
      first=""
      tick=$((tick + 1))
      sleep 0.1
    done
  else
    echo "Installing AFH..."
  fi

  local done="yes"
  wait "$worker" || done=""
  worker=""

  if [ -z "$done" ] || [ ! -f "$temp/version" ]; then
    local why="Something went wrong."
    if [ -f "$temp/failed" ]; then why="$(cat "$temp/failed")"
    elif [ -s "$temp/errors" ]; then why="$(tail -n 1 "$temp/errors")"
    fi
    if [ -n "$animate" ]; then
      frame "$shown" "$rest" $'\033[31m'"AFH wasn't installed: $why"$'\033[0m' "$first"
      printf '\n'
    else
      echo "AFH wasn't installed: $why" >&2
    fi
    exit 1
  fi

  local version next
  version="$(cat "$temp/version")"
  next="Go to a project folder and type: afh"
  if [ -f "$temp/added" ]; then next="Open a new terminal, go to a project folder and type: afh"; fi
  if [ -n "$animate" ]; then
    frame 1000 "$rest" $'\033[32m'"AFH $version is ready."$'\033[0m' "$first"
    printf '\n\n  %s\n\n' "$next"
  else
    echo "AFH $version is installed."
    echo "$next"
  fi
}

main "$@"
